'use strict';
/* Omni Business Suite Pro — Phase 3. All business data lives in the selected local folder. */
const ROOT='OmniSuitePro', DB='omnisuite-handle-db', STORE='handles', KEY='workspace';
const SLOTS=[['00:00','USA'],['03:00','USA'],['06:00','USA'],['09:00','UK'],['12:00','UK'],['15:00','UK'],['18:00','UK'],['21:00','USA']];
const STATES=['Draft','In Production','Ready','Scheduled','Published'];
const CHECKS=[['promptsReady','Prompts ready'],['clipsGenerated','All clips generated'],['voiceoverReady','Voiceover ready'],['videoEdited','Video editing completed'],['finalAttached','Final video attached'],['thumbnailReady','Thumbnail ready'],['titleDescriptionReady','Title & description ready'],['readyToPublish','Ready to publish'],['published','Published on Facebook']];
const TXT_FIELDS={title:'title.txt',description:'description.txt',prompts:'prompts.txt',voiceover:'voiceover.txt'};
const $=id=>document.getElementById(id), now=()=>new Date().toISOString();
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmtDate=d=>d?new Date(d).toLocaleString('en-IN',{dateStyle:'medium',timeStyle:'short'}):'—';
const fmtTime=s=>`${Math.floor((s||0)/60)}m ${String(Math.floor((s||0)%60)).padStart(2,'0')}s`;
const aspectLabel=(w,h)=>!w||!h?'Unknown':Math.abs(w/h-9/16)<.04?'9:16':Math.abs(w/h-16/9)<.06?'16:9':`${w}×${h}`;
const emptyData=()=>({schemaVersion:3,pages:[],videos:[],schedule:[],nextVideoNumber:1,createdAt:now(),updatedAt:now()});
let workspace=null, parentHandle=null, data=emptyData(), editingPageId=null, currentVideoId=null, currentTab='overview', currentView='dashboard';
let drafts={}, savedDrafts={}, dirty=new Set(), saveTimer=null, saveSequence=Promise.resolve(), selectedClipNumber=null;
let staged=new Map(), mediaUrls=new Map(), initDone=false, textFileEditing=null, extraSaveTimer=null, lastStatus='idle';
let plannerDate='',plannerPage='all',inventoryLayout='table',searchCache=new Map(),searchRequestId=0,searchTimer=null,clockTimer=null;
function toast(message,kind='info'){const el=$('toast');el.textContent=message;el.style.display='block';el.style.borderColor=kind==='error'?'#bc5266':'#4f729b';clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.style.display='none',6000)}
function setSaveStatus(status){lastStatus=status;const el=$('saveIndicator');if(el){el.textContent=status==='saving'?'Saving locally…':status==='dirty'?'Unsaved changes…':status==='error'?'Save failed — retry':status==='saved'?'✓ Saved locally':'All changes saved locally';el.style.color=status==='error'?'#ffaab3':status==='saved'?'#71dbaa':'#91a5c0'}}
function queued(fn){const run=saveSequence.catch(()=>{}).then(fn);saveSequence=run.catch(()=>{});return run}
function openDB(){return new Promise((ok,fail)=>{const req=indexedDB.open(DB,1);req.onupgradeneeded=()=>req.result.createObjectStore(STORE);req.onsuccess=()=>ok(req.result);req.onerror=()=>fail(req.error)})}
async function idb(mode,callback){const db=await openDB();try{return await new Promise((resolve,reject)=>{const tx=db.transaction(STORE,mode),req=callback(tx.objectStore(STORE));req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}finally{db.close()}}
const remember=h=>idb('readwrite',s=>s.put(h,KEY)), rememberGet=()=>idb('readonly',s=>s.get(KEY)), rememberForget=()=>idb('readwrite',s=>s.delete(KEY));
async function permit(h,ask=false){if(!h.queryPermission)return false;let p=await h.queryPermission({mode:'readwrite'});if(p!=='granted'&&ask)p=await h.requestPermission({mode:'readwrite'});return p==='granted'}
async function getSys(){if(!workspace)throw Error('Connect your local workspace first.');return workspace.getDirectoryHandle('system',{create:true})}
async function writeText(handle,text){const stream=await handle.createWritable();try{await stream.write(String(text));await stream.close()}catch(e){await stream.abort().catch(()=>{});throw e}}
async function writeJSON(handle,obj){await writeText(handle,JSON.stringify(obj,null,2)+'\n')}
async function getText(dir,name){try{return await(await dir.getFileHandle(name)).getFile().then(f=>f.text())}catch(e){if(e.name==='NotFoundError')return '';throw e}}
async function writeFileFromBlob(dir,name,file){const handle=await dir.getFileHandle(name,{create:true}),writer=await handle.createWritable();try{const reader=file.stream().getReader();for(;;){const {done,value}=await reader.read();if(done)break;await writer.write(value)}await writer.close()}catch(e){await writer.abort().catch(()=>{});throw e}}
function safeName(text){return(String(text||'page').normalize('NFKD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-zA-Z0-9_-]+/g,'-').replace(/^-+|-+$/g,'').slice(0,45)||'page')}
function makePageFolder(name,id){return `${safeName(name)}--${id.replace(/[^a-z0-9]/gi,'').slice(0,10)}`}
function isSafeLocalName(name){return typeof name==='string'&&name.length>0&&name.length<=120&&/^[\w.\- ]+$/i.test(name)&&name!=='.'&&name!=='..'&&!name.startsWith('.')}
function normalizedPage(p){if(!p||typeof p.id!=='string'||!p.id||typeof p.name!=='string'||!p.name.trim()||p.name.length>100||!['USA','UK','Mixed'].includes(p.audience))throw Error('Invalid page entry in metadata');return {id:p.id,name:p.name,audience:p.audience,notes:typeof p.notes==='string'?p.notes.slice(0,2000):'',folder:isSafeLocalName(p.folder)?p.folder:makePageFolder(p.name,p.id),createdAt:p.createdAt||now(),updatedAt:p.updatedAt||now()}}
function normalizedVideo(v,pageIds){if(!v||!/^VID-\d{4,}$/.test(v.id||'')||!pageIds.has(v.pageId)||typeof v.title!=='string'||v.title.length>300||typeof(v.description??'')!=='string'||(v.description||'').length>10000)throw Error('Invalid video entry in metadata');const clips=Array.isArray(v.clips)?v.clips:[];if(clips.length>2000)throw Error('Too many clips in video entry');return {id:v.id,pageId:v.pageId,title:v.title,description:v.description||'',status:STATES.includes(v.status)?v.status:'Draft',clipSeconds:[8,10].includes(Number(v.clipSeconds))?Number(v.clipSeconds):8,manualCount:typeof v.manualCount==='number'&&v.manualCount>=0?v.manualCount:null,promptCount:Number.isSafeInteger(v.promptCount)&&v.promptCount>=0?v.promptCount:clips.length,clips:clips.map((c,i)=>({number:i+1,status:['Pending','Generated','Approved'].includes(c.status)?c.status:'Pending',filename:isSafeLocalName(c.filename)?c.filename:null,updatedAt:c.updatedAt||now()})),thumbnailFile:isSafeLocalName(v.thumbnailFile)?v.thumbnailFile:null,thumbnailWidth:Number(v.thumbnailWidth)||null,thumbnailHeight:Number(v.thumbnailHeight)||null,finalFile:isSafeLocalName(v.finalFile)?v.finalFile:null,finalDuration:typeof v.finalDuration==='number'&&Number.isFinite(v.finalDuration)?v.finalDuration:null,videoWidth:Number(v.videoWidth)||null,videoHeight:Number(v.videoHeight)||null,extras:Array.isArray(v.extras)?v.extras.filter(isSafeLocalName).slice(0,500):[],checklist:Object.fromEntries(CHECKS.map(([k])=>[k,!!(v.checklist||{})[k]])),createdAt:v.createdAt||now(),updatedAt:v.updatedAt||now()}}
function isValidDate(s){if(typeof s!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(s))return false;const d=new Date(s+'T12:00:00Z');return !Number.isNaN(d.getTime())&&d.toISOString().slice(0,10)===s}
function slotKey(a){return `${a.date}|${a.pageId}|${a.time}`}
function normalizeSlot(s, pages, videos){
 if(!s||!isValidDate(s.date)||!pages.has(s.pageId)||!SLOTS.some(([t])=>t===s.time)||!videos.has(s.videoId)||videos.get(s.videoId).pageId!==s.pageId)throw Error('Invalid publishing assignment in metadata');
 if(typeof s.postUrl==='string'&&s.postUrl.length>1500)throw Error('Post URL too long');
 const url=String(s.postUrl||'').trim();if(url&&!/^https?:\/\//i.test(url))throw Error('Invalid post URL in metadata');
 return {date:s.date,pageId:s.pageId,time:s.time,videoId:s.videoId,published:!!s.published,postUrl:url,createdAt:s.createdAt||now(),updatedAt:s.updatedAt||now(),publishedAt:s.published?(s.publishedAt||s.updatedAt||now()):null}
}
function validate(raw){
 if(!raw||![1,2,3].includes(raw.schemaVersion)||!Array.isArray(raw.pages)||raw.pages.length>10000)throw Error('Invalid or unsupported metadata JSON');
 const pages=raw.pages.map(normalizedPage),ids=new Set(pages.map(p=>p.id));if(ids.size!==pages.length)throw Error('Duplicate page IDs');
 const videos=(raw.schemaVersion>=2&&Array.isArray(raw.videos)?raw.videos:[]).map(v=>normalizedVideo(v,ids));
 if(new Set(videos.map(v=>v.id)).size!==videos.length)throw Error('Duplicate video IDs');
 if(raw.schemaVersion===3&&(!Array.isArray(raw.schedule)||raw.schedule.length>200000))throw Error('Invalid publishing assignments');
 const vids=new Map(videos.map(v=>[v.id,v]));const schedule=(raw.schemaVersion===3?raw.schedule:[]).map(x=>normalizeSlot(x,ids,vids));
 if(new Set(schedule.map(slotKey)).size!==schedule.length)throw Error('Duplicate publishing time slots');
 const maxId=Math.max(0,...videos.map(v=>Number(v.id.slice(4))));
 return {schemaVersion:3,pages,videos,schedule,nextVideoNumber:Math.max(1,maxId+1,Number(raw.nextVideoNumber)||1),createdAt:raw.createdAt||now(),updatedAt:raw.updatedAt||now()}
}
async function writeMaster(obj){const sys=await getSys();await writeJSON(await sys.getFileHandle('metadata.json',{create:true}),obj)}
async function readMaster(){const sys=await getSys();let raw;try{raw=JSON.parse(await getText(sys,'metadata.json'));if(!raw||!raw.schemaVersion)throw Error('Empty or invalid data')}catch(e){if(e instanceof SyntaxError||e.message==='Empty or invalid data'){const h=await sys.getFileHandle('metadata.json',{create:false}).catch(()=>null);if(h)throw Error('Existing metadata is invalid. File was NOT overwritten. '+e.message);raw=emptyData()}else throw e}const result=validate(raw);if(raw.schemaVersion<3){const backup=await sys.getDirectoryHandle('backups',{create:true});await writeJSON(await backup.getFileHandle(`metadata-phase${raw.schemaVersion}-${Date.now()}.json`,{create:true}),raw);await writeMaster(result)}else if(!await sys.getFileHandle('metadata.json').catch(()=>null)){await writeMaster(result)}return result}
async function folderForVideo(v,create=false){const page=data.pages.find(p=>p.id===v.pageId);if(!page)throw Error('Video page no longer exists');const pageDir=await workspace.getDirectoryHandle(page.folder,{create});const record=await pageDir.getDirectoryHandle(v.id,{create});return record}
async function initializeRecordFolder(v,texts){const folder=await folderForVideo(v,true);await folder.getDirectoryHandle('clips',{create:true});await folder.getDirectoryHandle('versions',{create:true});for(const [k,fname] of Object.entries(TXT_FIELDS))await writeText(await folder.getFileHandle(fname,{create:true}),texts[k]||'');await writeJSON(await folder.getFileHandle('metadata.json',{create:true}),v);await writeJSON(await folder.getFileHandle('audit_log.json',{create:true}),[{at:now(),action:'Video created',detail:'Local video folder initialized'}]);return folder}
async function appendAudit(v,action,detail=''){try{const dir=await folderForVideo(v),h=await dir.getFileHandle('audit_log.json',{create:true});let old=[];try{old=JSON.parse(await(await h.getFile()).text())}catch(e){if(e.name!=='NotFoundError')throw e}if(!Array.isArray(old))throw Error('Invalid audit log');old.push({at:now(),action,detail});await writeJSON(h,old)}catch(e){toast('Saved, but audit log update failed: '+e.message,'error')}}
async function saveData(next,{videoId=null,action=null,detail=''}={}){next.updatedAt=now();await writeMaster(next);data=next;searchRequestId++;if(videoId)searchCache.delete(videoId);setSaveStatus('saved');if(videoId){const v=data.videos.find(x=>x.id===videoId);if(v){try{const dir=await folderForVideo(v);await writeJSON(await dir.getFileHandle('metadata.json',{create:true}),v)}catch(e){toast('Master saved, but video metadata mirror failed: '+e.message,'error')}if(action)await appendAudit(v,action,detail)}}renderShell()}
async function commitVideo(id,change,action,detail=''){return queued(async()=>{const next=structuredClone(data),v=next.videos.find(x=>x.id===id);if(!v)throw Error('Video not found');change(v);v.updatedAt=now();await saveData(next,{videoId:id,action,detail});return v})}
function videoById(id){return data.videos.find(v=>v.id===id)}
function pageById(id){return data.pages.find(p=>p.id===id)}
function makeClips(count){return Array.from({length:count},(_,i)=>({number:i+1,status:'Pending',filename:null,updatedAt:now()}))}
function countStats(v){const total=v.clips.length,done=v.clips.filter(c=>c.status!=='Pending').length,approved=v.clips.filter(c=>c.status==='Approved').length;return {total,done,approved,percent:total?Math.round(done/total*100):0}}
function parsePrompts(text){const regex=/^\s*(\d{1,4})[.)]\s+([^\n\r]+)\s*$/gm,matched=[...String(text).matchAll(regex)];const blocks=[];const errors=[];if(!matched.length&&text.trim())errors.push('No numbered prompts found. Use 1. 2. 3. or set a manual count.');if(matched.length>500)errors.push('More than 500 numbered items detected; review the file.');let expect=1;for(let i=0;i<matched.length;i++){const m=matched[i],n=Number(m[1]);if(n!==expect){errors.push(`Expected ${expect}. but found ${n}.`);expect=n}expect++;const raw=text.slice(m.index,i+1<matched.length?matched[i+1].index:text.length).trim();blocks.push({number:n,content:raw})}if(blocks.some(b=>/^\s*\d+[.)]\s*(title|conclusion|intro|summary)\b/i.test(b.content)))errors.push('One or more numbered items may be a heading, not a clip. Review manually.');return {count:blocks.length,blocks,errors:[...new Set(errors)]}}
function clearStaged(){for(const x of staged.values())if(x.url)URL.revokeObjectURL(x.url);staged.clear()}
function releaseMedia(prefix=null){for(const [key,url] of mediaUrls){if(!prefix||key.startsWith(prefix)){URL.revokeObjectURL(url);mediaUrls.delete(key)}}}
async function showConnected(handle){const candidate=handle.name===ROOT?handle:await handle.getDirectoryHandle(ROOT,{create:true});const previous=workspace;workspace=candidate;try{const incoming=await readMaster();data=incoming;searchCache.clear();searchRequestId++;parentHandle=handle;await remember(handle);releaseMedia();clearStaged();dirty.clear();drafts={};savedDrafts={};currentVideoId=null;renderAll();toast('Workspace connected: OmniSuitePro')}catch(e){workspace=previous;throw e}}
async function connect(saved=false){if(!window.showDirectoryPicker){toast('Use Google Chrome or another Chromium browser with local folder access.','error');return}try{let handle=saved?await rememberGet():await showDirectoryPicker({id:'omnisuite-downloads',mode:'readwrite',startIn:'downloads'});if(!handle){toast('No saved folder found. Select Downloads first.');return}if(!await permit(handle,true)){toast('Read/write permission not granted.','error');return}await showConnected(handle)}catch(e){if(e.name!=='AbortError')toast('Unable to connect: '+e.message,'error')}}
async function disconnect(){if(!confirm('Forget the saved workspace? Your Mac files will not be deleted.'))return;try{await flushText();await rememberForget();workspace=null;parentHandle=null;data=emptyData();searchCache.clear();searchRequestId++;currentVideoId=null;drafts={};dirty.clear();releaseMedia();clearStaged();renderAll();view('workspace');toast('Disconnected. No local files were deleted.')}catch(e){toast('Could not disconnect: '+e.message,'error')}}
function requireWorkspace(){if(workspace)return true;toast('Connect your local workspace first.');view('workspace');return false}
async function createPage(e){e.preventDefault();if(!requireWorkspace())return;const name=$('pageName').value.trim();if(!name)return;const values={name,audience:$('pageAudience').value,notes:$('pageNotes').value};try{await queued(async()=>{const next=structuredClone(data),at=now();if(editingPageId){const p=next.pages.find(p=>p.id===editingPageId);if(!p)throw Error('Page missing');Object.assign(p,values,{updatedAt:at})}else{const id=crypto.randomUUID();next.pages.push({id,...values,folder:makePageFolder(name,id),createdAt:at,updatedAt:at})}await saveData(next)});$('pageDialog').close();toast('Page saved in your Mac workspace.')}catch(err){toast('Page save failed: '+err.message,'error')}}
function showPageDialog(id=null){if(!requireWorkspace())return;editingPageId=id;const p=data.pages.find(x=>x.id===id);$('pageDialogTitle').textContent=p?'Edit Facebook Page':'Create Facebook Page';$('pageName').value=p?.name||'';$('pageAudience').value=p?.audience||'USA';$('pageNotes').value=p?.notes||'';$('pageDialog').showModal()}
async function deletePage(id){const p=pageById(id);if(!p)return;if(data.videos.some(v=>v.pageId===id)){toast('This page contains videos. Move or remove their records before deleting the page.','error');return}if(data.schedule.some(x=>x.pageId===id)){toast('This page has publishing assignments. Clear those slots first.','error');return}if(!confirm(`Delete page record "${p.name}"? Existing folders on your Mac will NOT be deleted.`))return;try{await queued(()=>saveData({...structuredClone(data),pages:data.pages.filter(x=>x.id!==id)}));toast('Page record removed; local folders remain unchanged.')}catch(e){toast('Delete failed: '+e.message,'error')}}
function showVideoDialog(){if(!requireWorkspace())return;if(!data.pages.length){toast('Create a Facebook page first.');view('pages');return}$('videoPage').innerHTML=data.pages.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('');$('newTitle').value='';$('newDescription').value='';$('newClipSeconds').value='8';$('videoDialog').showModal()}
async function createVideo(e){e.preventDefault();if(!requireWorkspace())return;const title=$('newTitle').value.trim(),description=$('newDescription').value.trim(),pageId=$('videoPage').value,clipSeconds=Number($('newClipSeconds').value);if(!title||!description||!pageById(pageId))return;const btn=$('submitVideo');btn.disabled=true;setSaveStatus('saving');try{let id;await queued(async()=>{const next=structuredClone(data),number=next.nextVideoNumber;id=`VID-${String(number).padStart(4,'0')}`;if(next.videos.some(v=>v.id===id))throw Error('Video number already exists');const t=now();const v={id,pageId,title,description,status:'Draft',clipSeconds,manualCount:null,promptCount:0,clips:[],thumbnailFile:null,thumbnailWidth:null,thumbnailHeight:null,finalFile:null,finalDuration:null,videoWidth:null,videoHeight:null,extras:[],checklist:Object.fromEntries(CHECKS.map(([k])=>[k,false])),createdAt:t,updatedAt:t};v.checklist.titleDescriptionReady=true;next.videos.push(v);next.nextVideoNumber=number+1;await initializeRecordFolder(v,{title,description,prompts:'',voiceover:''});await saveData(next,{videoId:id})});$('videoDialog').close();await openVideo(id);toast('Video created with its own TXT files and clips folder.')}catch(e){setSaveStatus('error');toast('Could not create video: '+e.message,'error')}finally{btn.disabled=false}}
async function duplicateVideo(id){const source=videoById(id);if(!source||!requireWorkspace())return;if(!confirm(`Duplicate ${source.id}? TXT files will be copied, but no videos or thumbnail media will be duplicated.`))return;try{await flushText();let newId;await queued(async()=>{const existing=videoById(id);const srcFolder=await folderForVideo(existing);const text={};for(const [field,name] of Object.entries(TXT_FIELDS))text[field]=await getText(srcFolder,name);const next=structuredClone(data),number=next.nextVideoNumber;newId=`VID-${String(number).padStart(4,'0')}`;const title=(text.title||existing.title).slice(0,290)+' (Copy)',t=now();const cloned={...structuredClone(existing),id:newId,title,description:text.description||existing.description,status:'Draft',clips:makeClips(existing.clips.length),thumbnailFile:null,thumbnailWidth:null,thumbnailHeight:null,finalFile:null,finalDuration:null,videoWidth:null,videoHeight:null,extras:[],checklist:Object.fromEntries(CHECKS.map(([k])=>[k,false])),createdAt:t,updatedAt:t};cloned.checklist.promptsReady=cloned.clips.length>0;cloned.checklist.titleDescriptionReady=!!(title.trim()&&cloned.description.trim());next.videos.push(cloned);next.nextVideoNumber=number+1;await initializeRecordFolder(cloned,{...text,title});await saveData(next,{videoId:newId})});await openVideo(newId);toast('Duplicated TXT and video metadata without copying media.')}catch(e){toast('Duplication failed: '+e.message,'error')}}
function runDownload(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),3000)}
function exportData(){if(!requireWorkspace())return;runDownload(new Blob([JSON.stringify(data,null,2)+'\n'],{type:'application/json'}),'omnisuite-metadata-'+new Date().toISOString().slice(0,10)+'.json');toast('Metadata JSON export started. TXT and media are not included.')}
async function importData(file){if(!file)return;if(!requireWorkspace())return;try{await flushText();const incoming=validate(JSON.parse(await file.text())),pages=new Map(data.pages.map(p=>[p.id,p])),videos=new Map(data.videos.map(v=>[v.id,v]));const assignments=new Map(data.schedule.map(x=>[slotKey(x),x]));for(const p of incoming.pages)pages.set(p.id,p);for(const v of incoming.videos){if(videos.has(v.id)&&videos.get(v.id).pageId!==v.pageId)throw Error(`Conflict for ${v.id}: different page IDs`);videos.set(v.id,v)}for(const a of incoming.schedule)assignments.set(slotKey(a),a);if(!confirm(`Import/merge ${incoming.pages.length} pages, ${incoming.videos.length} videos and ${incoming.schedule.length} publishing assignments? Media and TXT content are NOT included. Existing metadata with matching IDs may be replaced.`))return;await queued(async()=>{const merged=validate({...data,pages:[...pages.values()],videos:[...videos.values()],schedule:[...assignments.values()],nextVideoNumber:Math.max(data.nextVideoNumber,incoming.nextVideoNumber)});await saveData(merged)});toast('Metadata imported. Files referenced by an imported record must already exist in this workspace.')}catch(e){toast('Import failed: '+e.message,'error')}finally{$('importFile').value=''}}

/* ----------------------------- Video editing ----------------------------- */
async function readVideoTexts(v){const folder=await folderForVideo(v);const obj={};for(const [name,filename] of Object.entries(TXT_FIELDS))obj[name]=await getText(folder,filename);return obj}
async function openVideo(id){if(!requireWorkspace())return;try{await flushText()}catch(e){toast('Save your text before switching video: '+e.message,'error');return}clearStaged();releaseMedia('stage:');currentVideoId=id;currentTab='overview';textFileEditing=null;const v=videoById(id);if(!v){toast('Video record missing.','error');return}try{drafts=await readVideoTexts(v)}catch(e){drafts={title:v.title,description:v.description,prompts:'',voiceover:''};toast('Cannot read video TXT folder: '+e.message,'error')}savedDrafts={...drafts};dirty.clear();view('details');renderDetail();}
async function textVersion(folder,filename,oldContent){if(!oldContent)return;const ver=await folder.getDirectoryHandle('versions',{create:true});const stamp=new Date().toISOString().replace(/[:.]/g,'-');const unique=crypto.randomUUID().slice(0,5);await writeText(await ver.getFileHandle(`${filename.replace('.txt','')}-${stamp}-${unique}.txt`,{create:true}),oldContent)}
function editText(field,value){if(!currentVideoId||!(field in TXT_FIELDS))return;drafts[field]=value;if(drafts[field]===savedDrafts[field])dirty.delete(field);else dirty.add(field);setSaveStatus(dirty.size?'dirty':'saved');if(field==='prompts')updatePromptFeedback();if(field==='title'){$('detailTitleLive')&&($('detailTitleLive').textContent=value||'Untitled video')}clearTimeout(saveTimer);if(dirty.size)saveTimer=setTimeout(()=>flushText().catch(e=>toast('Auto-save failed: '+e.message,'error')),950)}
async function flushText(){clearTimeout(saveTimer);if(!dirty.size){await saveSequence;if(textFileEditing?.dirty)return saveExtraEditor(true);return;}const id=currentVideoId,changes=Object.fromEntries([...dirty].map(k=>[k,drafts[k]]));dirty.clear();setSaveStatus('saving');try{return await queued(async()=>{const v=videoById(id);if(!v)throw Error('Video no longer exists');const folder=await folderForVideo(v);const edited=[];for(const [field,text] of Object.entries(changes)){const filename=TXT_FIELDS[field],handle=await folder.getFileHandle(filename,{create:true}),old=await(await handle.getFile()).text();if(text===old){savedDrafts[field]=text;continue}await textVersion(folder,filename,old);await writeText(handle,text);edited.push(field);if(currentVideoId===id)savedDrafts[field]=text}
 if(!edited.length){setSaveStatus('saved');return}const next=structuredClone(data),record=next.videos.find(r=>r.id===id);if(edited.includes('title'))record.title=changes.title.slice(0,300);if(edited.includes('description'))record.description=changes.description.slice(0,10000);
 if(edited.includes('prompts')){const parsed=parsePrompts(changes.prompts),count=record.manualCount===null?parsed.count:record.manualCount;record.promptCount=count;if(!parsed.errors.length||record.manualCount!==null){if(count>=record.clips.length){record.clips.push(...makeClips(count-record.clips.length).map((c,i)=>({...c,number:record.clips.length+i+1})))}else if(record.clips.slice(count).every(c=>!c.filename&&c.status==='Pending'))record.clips=record.clips.slice(0,count)}record.checklist.promptsReady=count>0&&(!parsed.errors.length||record.manualCount!==null)}
 if(edited.includes('voiceover'))record.checklist.voiceoverReady=!!changes.voiceover.trim();record.checklist.titleDescriptionReady=!!((record.title||'').trim()&&(record.description||'').trim());record.checklist.clipsGenerated=record.clips.length>0&&record.clips.every(c=>c.status!=='Pending');record.updatedAt=now();await saveData(next,{videoId:id,action:'TXT content saved',detail:edited.map(k=>TXT_FIELDS[k]).join(', ')});setSaveStatus(dirty.size?'dirty':'saved');if(currentVideoId===id){renderDetailHeader();if(currentTab==='prompts')refreshClipPanel()}});if(textFileEditing?.dirty)await saveExtraEditor(true)}catch(e){for(const field of Object.keys(changes))if(drafts[field]===changes[field])dirty.add(field);setSaveStatus('error');throw e}}
async function saveNow(){try{await flushText();toast('All text changes saved locally.')}catch(e){toast('Save failed: '+e.message,'error')}}
function uploadText(field,file){if(!file)return;if(!file.name.toLowerCase().endsWith('.txt')&&file.type!=='text/plain'){toast('Please select a TXT file.','error');return}if(file.size>5_000_000){toast('TXT file exceeds the 5 MB editor limit.','error');return}file.text().then(str=>{drafts[field]=str;const el=$(`edit-${field}`);if(el)el.value=str;editText(field,str);if(field==='prompts')renderDetail();toast(file.name+' loaded into editor. Auto-save is enabled.')}).catch(e=>toast('Could not read TXT: '+e.message,'error'))}
async function changeClipSeconds(seconds){if(![8,10].includes(seconds))return;try{await flushText();await commitVideo(currentVideoId,v=>v.clipSeconds=seconds,'Clip duration changed',seconds+'s per clip');renderDetail();toast('Duration updated.')}catch(e){toast(e.message,'error')}}
async function applyPromptCount(manual=false){const v=videoById(currentVideoId);if(!v)return;try{await flushText();let count;if(manual){count=Number($('manualCount')?.value);if(!Number.isInteger(count)||count<0||count>500){toast('Choose a prompt count between 0 and 500.','error');return}}else count=parsePrompts(drafts.prompts||'').count;const trimmed=v.clips.slice(count);if(trimmed.some(c=>c.filename||c.status!=='Pending')){toast('Cannot remove clips with generated media or progress. Change those clips first.','error');return}await commitVideo(v.id,r=>{r.manualCount=manual?count:null;r.promptCount=count;r.clips=Array.from({length:count},(_,i)=>r.clips[i]||{number:i+1,status:'Pending',filename:null,updatedAt:now()});r.checklist.promptsReady=count>0;r.checklist.clipsGenerated=count>0&&r.clips.every(c=>c.status!=='Pending')},'Prompt count updated',manual?`Manual override: ${count}`:`Numbered prompts: ${count}`);renderDetail();toast('Clip tasks updated to '+count)}catch(e){toast('Could not update clip count: '+e.message,'error')}}
async function updateClipStatus(number,status){if(!['Pending','Generated','Approved'].includes(status))return;try{await flushText();await commitVideo(currentVideoId,v=>{const clip=v.clips.find(c=>c.number===number);if(!clip)throw Error('Clip not found');clip.status=status;clip.updatedAt=now();v.checklist.clipsGenerated=v.clips.length>0&&v.clips.every(c=>c.status!=='Pending')},'Clip status changed',`Clip ${number} → ${status}`);renderDetail()}catch(e){toast('Clip update failed: '+e.message,'error')}}
async function toggleCheck(key,checked){if(!CHECKS.some(([k])=>k===key))return;try{await flushText();await commitVideo(currentVideoId,v=>{v.checklist[key]=checked;if(key==='published'&&checked)v.status='Published';if(key==='readyToPublish'&&checked&&v.status==='Draft')v.status='Ready'},'Checklist updated',`${key}: ${checked?'Complete':'Pending'}`);renderDetail()}catch(e){toast('Checklist update failed: '+e.message,'error')}}
async function changeStatus(status){if(!STATES.includes(status))return;try{await flushText();await commitVideo(currentVideoId,v=>{v.status=status;v.checklist.published=status==='Published';if(status==='Ready')v.checklist.readyToPublish=true},'Production stage updated',status);renderDetail()}catch(e){toast('Status update failed: '+e.message,'error')}}
function extensionFor(file,kind){const ext=(file.name.split('.').pop()||'').toLowerCase();const allowed=kind==='thumbnail'?['png','jpg','jpeg','webp','gif','avif']:['mp4','mov','webm','m4v'];if(!allowed.includes(ext))throw Error(`Unsupported ${kind==='thumbnail'?'image':'video'} extension: .${ext}`);return ext}
async function probeImage(file){try{const bitmap=await createImageBitmap(file);const result={width:bitmap.width,height:bitmap.height};bitmap.close();return result}catch{return {width:null,height:null}}}
function probeVideo(file){return new Promise(resolve=>{const vid=document.createElement('video'),src=URL.createObjectURL(file);let finished=false;const end=result=>{if(finished)return;finished=true;vid.removeAttribute('src');vid.load();URL.revokeObjectURL(src);resolve(result)};vid.preload='metadata';vid.onloadedmetadata=()=>end({duration:Number.isFinite(vid.duration)?vid.duration:null,width:vid.videoWidth||null,height:vid.videoHeight||null});vid.onerror=()=>end({duration:null,width:null,height:null});vid.src=src;setTimeout(()=>end({duration:null,width:null,height:null}),12000)})}
function stageFile(kind,file,number=null){if(!file||!requireWorkspace()||!currentVideoId)return;try{const ext=extensionFor(file,kind);const key=kind==='clip'?`clip:${number}`:kind;const old=staged.get(key);if(old?.url)URL.revokeObjectURL(old.url);staged.set(key,{file,ext,url:URL.createObjectURL(file)});renderDetail();toast(`${file.name} ready to preview. Click Save to ERP to copy it.`)}catch(e){toast(e.message,'error')}}
async function mediaUrl(v,filename){if(!filename)return null;const key=`${v.id}|${filename}`;if(mediaUrls.has(key))return mediaUrls.get(key);try{const dir=await folderForVideo(v),h=filename.startsWith('clip_')?await(await dir.getDirectoryHandle('clips')).getFileHandle(filename):await dir.getFileHandle(filename),f=await h.getFile();const url=URL.createObjectURL(f);mediaUrls.set(key,url);return url}catch(e){if(e.name==='NotFoundError')return null;throw e}}
async function saveStaged(kind,number=null){const key=kind==='clip'?`clip:${number}`:kind,item=staged.get(key);if(!item)return toast('Choose or drop a file first.');const id=currentVideoId;setSaveStatus('saving');try{await flushText();const v=videoById(id),dir=await folderForVideo(v),child=kind==='clip'?await dir.getDirectoryHandle('clips',{create:true}):dir;const filename=kind==='clip'?`clip_${String(number).padStart(3,'0')}.${item.ext}`:kind==='thumbnail'?`thumbnail.${item.ext}`:`final_video.${item.ext}`;const oldFilename=kind==='clip'?v.clips.find(c=>c.number===number)?.filename:kind==='thumbnail'?v.thumbnailFile:v.finalFile;
 await writeFileFromBlob(child,filename,item.file);const info=kind==='final'?await probeVideo(item.file):kind==='thumbnail'?await probeImage(item.file):null;
 await commitVideo(id,r=>{if(kind==='thumbnail'){r.thumbnailFile=filename;r.thumbnailWidth=info.width;r.thumbnailHeight=info.height;r.checklist.thumbnailReady=true}else if(kind==='final'){r.finalFile=filename;r.finalDuration=info.duration;r.videoWidth=info.width;r.videoHeight=info.height;r.checklist.finalAttached=true}else{const clip=r.clips.find(c=>c.number===number);if(!clip)throw Error('Clip task missing');clip.filename=filename;clip.status='Generated';clip.updatedAt=now();r.checklist.clipsGenerated=r.clips.every(c=>c.status!=='Pending')}},kind==='clip'?'Clip saved to ERP':kind==='final'?'Final video saved to ERP':'Thumbnail saved to ERP',filename);
 if(oldFilename&&oldFilename!==filename){try{await child.removeEntry(oldFilename)}catch(e){toast('New file saved; older file could not be removed: '+e.message,'error')}}
 releaseMedia(`${id}|`);URL.revokeObjectURL(item.url);staged.delete(key);renderDetail();toast('Saved local copy: '+filename)}catch(e){setSaveStatus('error');toast('File save failed: '+e.message,'error')}}
async function openOriginalMedia(kind,number=null){const v=videoById(currentVideoId);if(!v)return;const filename=kind==='final'?v.finalFile:kind==='thumbnail'?v.thumbnailFile:v.clips.find(c=>c.number===number)?.filename;if(!filename){toast('No saved media file yet.');return}try{const url=await mediaUrl(v,filename);if(!url)throw Error('File is missing on disk');window.open(url,'_blank','noopener,noreferrer')}catch(e){toast('Could not preview file: '+e.message,'error')}}
async function updateExtraFile(file=null,createName=null){const v=videoById(currentVideoId);if(!v)return;const name=createName||file?.name;if(!isSafeLocalName(name)||!name.toLowerCase().endsWith('.txt')||Object.values(TXT_FIELDS).includes(name)||['metadata.json','audit_log.json'].includes(name)){toast('Use a simple TXT filename such as notes.txt.','error');return}if(file&&file.size>5_000_000){toast('TXT must be under 5 MB.','error');return}try{await flushText();const folder=await folderForVideo(v),existing=await folder.getFileHandle(name).catch(()=>null);if(existing&&!confirm(`Replace existing local TXT file ${name}? Previous content will be versioned.`))return;if(existing)await textVersion(folder,name,await(await existing.getFile()).text());await writeText(await folder.getFileHandle(name,{create:true}),file?await file.text():'');await commitVideo(v.id,r=>{if(!r.extras.includes(name))r.extras.push(name)},'Supporting TXT saved',name);renderDetail();toast('TXT saved: '+name)}catch(e){toast('TXT save failed: '+e.message,'error')}}
async function openExtraEditor(name){try{await flushText();const folder=await folderForVideo(videoById(currentVideoId));const text=await getText(folder,name);textFileEditing={name,text,saved:text,dirty:false};renderDetail()}catch(e){toast('Could not read TXT: '+e.message,'error')}}
async function saveExtraEditor(silent=false){
 clearTimeout(extraSaveTimer);if(!textFileEditing)return;const id=currentVideoId,{name,text}=textFileEditing;if(!textFileEditing.dirty){if(!silent)toast('TXT has no unsaved changes.');return}
 setSaveStatus('saving');try{await queued(async()=>{const v=videoById(id),folder=await folderForVideo(v),h=await folder.getFileHandle(name,{create:true}),old=await(await h.getFile()).text();if(old!==text){await textVersion(folder,name,old);await writeText(h,text);const next=structuredClone(data);next.videos.find(x=>x.id===id).updatedAt=now();await saveData(next,{videoId:id,action:'Supporting TXT edited',detail:name})}});if(currentVideoId===id&&textFileEditing?.name===name){textFileEditing.saved=text;textFileEditing.dirty=textFileEditing.text!==text;if(textFileEditing.dirty)extraSaveTimer=setTimeout(()=>saveExtraEditor(true).catch(()=>{}),950)}setSaveStatus('saved');if(!silent){renderDetail();toast('TXT file saved.')}}catch(e){if(textFileEditing?.name===name)textFileEditing.dirty=true;setSaveStatus('error');toast('TXT edit failed: '+e.message,'error');throw e}}

async function removeExtra(name){const v=videoById(currentVideoId);if(!v||!confirm(`Delete ${name} from this local video folder? This action removes the file.`))return;try{await flushText();const dir=await folderForVideo(v);await dir.removeEntry(name);await commitVideo(v.id,r=>r.extras=r.extras.filter(x=>x!==name),'Supporting TXT deleted',name);if(textFileEditing?.name===name)textFileEditing=null;renderDetail();toast('TXT file deleted: '+name)}catch(e){toast('Delete failed: '+e.message,'error')}}

/* ----------------------------- View rendering ----------------------------- */
function currentPage(){return data.pages.find(p=>p.id===videoById(currentVideoId)?.pageId)}
function view(name){currentView=name;document.querySelectorAll('.view').forEach(x=>x.classList.toggle('active',x.id===name));document.querySelectorAll('.nav-link').forEach(b=>b.classList.toggle('active',b.dataset.view===name));$('sidebar').classList.remove('open');const names={dashboard:'Dashboard',pages:'Page Manager',production:'Production',inventory:'Video Inventory',details:'Video Details',planner:'Publishing Planner',world:'World Clocks',search:'Global Search',workspace:'Settings'};$('currentViewName').textContent=names[name]||name;if(name==='details')renderDetail();if(name==='planner')renderPlanner();if(name==='world')renderClocks();if(name==='search')renderGlobalSearch();}
function tagStatus(status){return `<span class="status-tag ${esc(status.toLowerCase().replace(/\s+/g,'-'))}">${esc(status)}</span>`}
function thumbMarkup(v,cls='thumbnail'){return `<div class="${cls}" data-thumb="${esc(v.id)}">${v.thumbnailFile?`<img alt="Thumbnail of ${esc(v.title)}" data-thumb-image="${esc(v.id)}">`:'<span style="font-size:28px">▶</span>'}</div>`}
function renderThumbnails(){document.querySelectorAll('img[data-thumb-image]').forEach(async img=>{const id=img.dataset.thumbImage,v=videoById(id);if(!v||!v.thumbnailFile)return;try{const url=await mediaUrl(v,v.thumbnailFile);if(img.isConnected&&img.dataset.thumbImage===id){if(url)img.src=url;else{img.parentElement.innerHTML='<span class="hint">Missing thumbnail</span>'}}}catch(e){if(img.isConnected)img.alt='Preview unavailable'}})}
function renderShell(){const connected=!!workspace;$('connectionPill').textContent=connected?'● Workspace connected':'● Disconnected';$('connectionPill').style.color=connected?'#73e9a8':'#ff9ba5';$('sideConnection').textContent=connected?ROOT:'Not connected';$('sideDetails').textContent=connected?'Mac folder connected':'Select Downloads in Chrome';$('workspaceStatus').textContent=connected?'Connected · '+ROOT+' · Local files enabled':'Not connected — choose Downloads in Chrome';$('mPages').textContent=data.pages.length;$('mVideos').textContent=data.videos.length;$('mProduction').textContent=data.videos.filter(v=>['Draft','In Production'].includes(v.status)).length;$('mReady').textContent=`${data.videos.filter(v=>v.status==='Ready').length} / ${data.videos.filter(v=>v.status==='Published').length}`;$('pageCount').textContent=data.pages.length+' pages';$('todayDate').textContent=new Intl.DateTimeFormat('en-IN',{dateStyle:'medium',timeZone:'Asia/Kolkata'}).format(new Date());
 $('slotsPreview').innerHTML=SLOTS.map(([time,audience])=>`<div class="slot-row"><time class="slot-time">${time}</time><span class="hint">Per page · IST</span><span class="tag">${audience}</span></div>`).join('');$('settingsSlots').innerHTML=SLOTS.map(([time,aud])=>`<div><strong>${time}</strong><small>${aud}</small></div>`).join('');
 $('dashPages').innerHTML=data.pages.length?data.pages.slice(0,9).map(p=>`<div class="slot-row"><b>${esc(p.name)}</b><span class="tag">${esc(p.audience)}</span><span class="hint">${data.videos.filter(v=>v.pageId===p.id).length} videos</span></div>`).join(''):'<div class="empty">No pages yet. Connect a folder and create your first page.</div>';
 const recent=[...data.videos].sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt)).slice(0,5);$('dashboardVideos').innerHTML=recent.length?recent.map(v=>`<div class="mini-video">${thumbMarkup(v,'thumb')}<div class="body"><strong>${esc(v.title||v.id)}</strong><span class="hint">${esc(v.id)} · ${esc(pageById(v.pageId)?.name||'Unknown page')}</span></div>${tagStatus(v.status)}<button class="btn btn-outline btn-small" data-open-video="${esc(v.id)}">Open</button></div>`).join(''):'<div class="empty">Nothing in production yet. Create a page and start your first video.</div>';
 $('pagesTable').innerHTML=data.pages.length?`<div class="table-scroll"><table class="erp-table"><thead><tr><th>Page name</th><th>Audience</th><th>Videos</th><th>Daily slots</th><th>Actions</th></tr></thead><tbody>${data.pages.map(p=>`<tr><td><strong>${esc(p.name)}</strong></td><td><span class="tag">${esc(p.audience)}</span></td><td>${data.videos.filter(v=>v.pageId===p.id).length}</td><td>8</td><td><button class="btn btn-outline btn-small" data-page-edit="${esc(p.id)}">Edit</button> <button class="btn btn-danger btn-small" data-page-delete="${esc(p.id)}">Delete</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No pages configured. Select “+ New Page” to begin.</div>';
 for(const prefix of ['production','inventory']){const el=$(`${prefix}PageFilter`),old=el.value;el.innerHTML='<option value="all">All Facebook pages</option>'+data.pages.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('');el.value=data.pages.some(p=>p.id===old)?old:'all'}
 renderVideoLists();renderPhase3Shell();renderThumbnails();if(currentVideoId)renderDetailHeader();}
function filteredRecords(prefix){const q=$(`${prefix}Search`).value.trim().toLowerCase(),page=$(`${prefix}PageFilter`).value,status=$(`${prefix}StatusFilter`).value;return [...data.videos].filter(v=>(page==='all'||v.pageId===page)&&(status==='all'||v.status===status)&&(`${v.id} ${v.title} ${v.description} ${pageById(v.pageId)?.name||''}`).toLowerCase().includes(q)).sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt))}
function renderVideoLists(){const pv=filteredRecords('production'),iv=filteredRecords('inventory');$('productionList').innerHTML=pv.length?pv.map(v=>{const s=countStats(v);return `<article class="video-card">${thumbMarkup(v)}<div class="card-inner"><div class="card-meta"><span class="hint">${esc(v.id)} · ${esc(pageById(v.pageId)?.name||'')}</span>${tagStatus(v.status)}</div><h3>${esc(v.title||'(Untitled)')}</h3><div class="progress-label"><span>Generated clips</span><span>${s.done} / ${s.total}</span></div><div class="progress-track"><span style="width:${s.percent}%"></span></div><div class="card-bottom"><span class="hint">${v.clipSeconds}s/clip · ${fmtTime(v.promptCount*v.clipSeconds)}</span><button class="btn btn-primary btn-small" data-open-video="${esc(v.id)}">Open</button></div></div></article>`}).join(''):'<div class="empty">No matching videos. Create your first video product to begin tracking production.</div>';
 $('inventoryTable').innerHTML=iv.length?`<div class="table-scroll"><table class="erp-table"><thead><tr><th>Video</th><th>Page</th><th>Clips</th><th>Est. duration</th><th>Status</th><th>Last updated</th><th></th></tr></thead><tbody>${iv.map(v=>{const s=countStats(v);return `<tr><td><div class="title-cell">${thumbMarkup(v,'thumb')}<div><strong class="wrap">${esc(v.title)}</strong><div class="hint">${esc(v.id)}</div></div></div></td><td>${esc(pageById(v.pageId)?.name||'—')}</td><td>${s.done}/${s.total}</td><td>${fmtTime(v.promptCount*v.clipSeconds)}</td><td>${tagStatus(v.status)}</td><td>${fmtDate(v.updatedAt)}</td><td><button class="btn btn-outline btn-small" data-open-video="${esc(v.id)}">Open</button></td></tr>`}).join('')}</tbody></table></div>`:'<div class="empty">No matching video records.</div>';renderThumbnails();renderKanban()}
function renderDetailHeader(){const v=videoById(currentVideoId);if(!v)return;const s=countStats(v);$('detailsHeader').innerHTML=`<div class="detail-heading"><div><span class="eyebrow">${esc(v.id)} · ${esc(pageById(v.pageId)?.name||'Unknown page')}</span><h1 id="detailTitleLive">${esc(drafts.title??v.title)}</h1><div class="detail-meta">${tagStatus(v.status)}<span class="hint">${v.clipSeconds}s clips</span><span class="hint">${s.done}/${s.total} generated</span><span class="hint">Last updated ${esc(fmtDate(v.updatedAt))}</span></div></div><div class="button-row"><button class="btn btn-outline" data-duplicate="${esc(v.id)}">Duplicate TXT & Record</button><button class="btn btn-primary" id="saveNow">Save Now</button></div></div>`}
function textarea(field,label,rows=4,large=false){return `<label class="form-label">${label}<textarea class="field text-editor ${large?'large':''}" id="edit-${field}" data-edit-text="${field}" ${field==='title'?'maxlength="300"':field==='description'?'maxlength="10000"':''} rows="${rows}" spellcheck="true">${esc(drafts[field]??'')}</textarea></label>`}
function makePreview(kind,number=null){const v=videoById(currentVideoId),key=kind==='clip'?`clip:${number}`:kind,st=staged.get(key);const fname=kind==='thumbnail'?v.thumbnailFile:kind==='final'?v.finalFile:v.clips.find(c=>c.number===number)?.filename;
 if(st)return `<div class="media-preview ${kind==='thumbnail'?'portrait':''}">${kind==='thumbnail'?`<img src="${esc(st.url)}" alt="Staged thumbnail">`:`<video src="${esc(st.url)}" controls preload="metadata"></video>`}</div><span class="hint">Not saved to ERP yet · ${esc(st.file.name)} (${(st.file.size/1048576).toFixed(1)} MB)</span>`;
 if(fname)return `<div class="media-preview"><${kind==='thumbnail'?'img':'video'} ${kind==='thumbnail'?'alt="Saved thumbnail"':'controls preload="metadata"'} data-saved-media="${esc(key)}" /></div><span class="hint">Saved file: ${esc(fname)}</span>`;
 return `<div class="media-preview"><span class="hint">No ${kind==='clip'?'clip video':kind==='final'?'final video':'thumbnail'} saved yet</span></div>`}
function dropZone(kind,number=null){return `<div class="file-drop" tabindex="0" role="button" data-drop-kind="${kind}" ${number!==null?`data-drop-number="${number}"`:''}><div><strong>⬆ Drop ${kind==='thumbnail'?'a thumbnail':'a video'} here</strong><small style="display:block;margin-top:6px">or click to browse Mac files</small></div></div>`}
function renderOverview(v){const completed=CHECKS.filter(([key])=>v.checklist[key]).length;return `<div class="detail-grid"><div class="detail-stack"><article class="panel"><div class="panel-heading"><h2>Product Information</h2><span class="hint">Automatically saved to TXT</span></div>${textarea('title','Video title',2)}${textarea('description','Facebook description / caption',6,true)}<label class="form-label">Production stage<select class="field" id="detailStatus">${STATES.map(x=>`<option ${x===v.status?'selected':''}>${x}</option>`).join('')}</select></label><p class="hint">Edits are written to title.txt and description.txt after you pause typing.</p></article><article class="panel"><div class="panel-heading"><h2>Production Checklist</h2><span class="hint">${completed}/${CHECKS.length} complete</span></div><div class="progress-track" style="margin-bottom:14px"><span style="width:${Math.round(completed/CHECKS.length*100)}%"></span></div><div class="checklist">${CHECKS.map(([key,label])=>`<label class="check-row"><input type="checkbox" data-check="${key}" ${v.checklist[key]?'checked':''}><span>${label}</span>${v.checklist[key]?'<span class="status-tag ready">Done</span>':''}</label>`).join('')}</div></article></div><div class="detail-stack"><article class="panel"><div class="panel-heading"><h2>Content Preview</h2><button class="text-button" data-tab-open="files">Manage media →</button></div>${v.thumbnailFile?makePreview('thumbnail'):'<div class="media-preview"><span class="hint">Thumbnail not attached</span></div>'}<div class="inline-stats" style="margin-top:14px"><span>Prompts: <strong>${v.promptCount}</strong></span><span>Est. length: <strong>${fmtTime(v.promptCount*v.clipSeconds)}</strong></span></div><div class="button-row"><button class="btn btn-outline" data-tab-open="prompts">Prompts & Clips</button><button class="btn btn-outline" data-tab-open="voiceover">Voiceover</button></div></article><article class="panel"><h2>Local Record</h2><p class="hint">Your TXT files and metadata are inside this video's dedicated folder. Video media is copied only when you choose Save to ERP.</p><p class="hint">${esc(v.id)} · ${esc(pageById(v.pageId)?.name||'')}</p><p class="hint">Estimated duration uses prompt count × ${v.clipSeconds}s. Edited final video duration may differ.</p></article></div></div>`}
function clipsPanel(v){const parsed=parsePrompts(drafts.prompts||''),blocks=parsed.blocks;return `<div class="clip-list">${v.clips.length?v.clips.map(c=>{const snippet=blocks.find(b=>b.number===c.number)?.content||'';return `<div class="clip-item"><div class="clip-head"><div style="min-width:0"><b>Clip ${String(c.number).padStart(3,'0')}</b><div class="clip-snippet">${esc(snippet.slice(0,380))||'<span class="muted">No matched numbered prompt</span>'}</div>${c.filename?`<span class="hint">${esc(c.filename)}</span>`:''}</div><div class="clip-actions"><select class="field" data-clip-status="${c.number}" aria-label="Clip ${c.number} status"><option ${c.status==='Pending'?'selected':''}>Pending</option><option ${c.status==='Generated'?'selected':''}>Generated</option><option ${c.status==='Approved'?'selected':''}>Approved</option></select><button class="btn btn-outline btn-small" data-upload-clip="${c.number}">Attach</button>${c.filename||staged.has(`clip:${c.number}`)?`<button class="btn btn-outline btn-small" data-clip-preview="${c.number}">${selectedClipNumber===c.number?'Hide':'Preview'}</button>`:''}</div></div>${staged.has(`clip:${c.number}`)?`<div style="margin-top:11px">${makePreview('clip',c.number)}<div class="asset-actions"><button class="btn btn-primary btn-small" data-save-asset="clip" data-number="${c.number}">Save Clip to ERP</button></div></div>`:''}${selectedClipNumber===c.number&&!staged.has(`clip:${c.number}`)&&c.filename?`<div style="margin-top:11px">${makePreview('clip',c.number)}</div>`:''}</div>`}).join(''):'<div class="empty">No clip tasks yet. Paste numbered prompts and apply the detected count.</div>'}</div>`}
function renderPrompts(v){const parsed=parsePrompts(drafts.prompts||''),count=v.manualCount===null?parsed.count:v.manualCount,s=countStats(v);return `<div class="detail-grid"><div class="detail-stack"><article class="panel"><div class="panel-heading"><h2>Veo Prompt Editor</h2><button class="btn btn-outline btn-small" id="uploadPrompts">Upload TXT</button></div><div class="helper">Number your prompts <b>1.</b>, <b>2.</b>, <b>3.</b> and so on. Unnumbered titles and conclusions are ignored when possible. Fix ambiguous detection manually.</div>${textarea('prompts','Original Veo prompts · stored in prompts.txt',14,true)}<div id="promptFeedback"></div><div class="form-grid" style="margin-top:15px"><label class="form-label">Clip duration<select id="clipSecondsSelect" class="field"><option value="8" ${v.clipSeconds===8?'selected':''}>8 seconds</option><option value="10" ${v.clipSeconds===10?'selected':''}>10 seconds</option></select></label><label class="form-label">Manual prompt count<input id="manualCount" class="field" type="number" min="0" max="500" step="1" value="${count}"></label></div><div class="button-row"><button class="btn btn-primary" id="applyManualCount">Apply Manual Count</button><button class="btn btn-outline" id="useDetectedCount">Use Detected Count</button><button class="btn btn-outline" id="savePromptsNow">Save TXT Now</button></div><div class="hint" style="margin-top:8px">If your prompt TXT contains headings, manually fix it or override the count. Changes won't delete completed clip tasks.</div></article></div><div class="detail-stack"><article class="panel"><div class="panel-heading"><h2>Individual Clip Tracker</h2><span class="hint">${s.done}/${s.total} generated · ${s.approved} approved</span></div><div class="progress-track" style="margin-bottom:14px"><span style="width:${s.percent}%"></span></div><div id="clipPanel">${clipsPanel(v)}</div></article></div></div>`}
function renderVoiceover(v){return `<div class="detail-grid"><article class="panel"><div class="panel-heading"><h2>Voiceover TXT Editor</h2><button class="btn btn-outline btn-small" id="uploadVoiceover">Upload TXT</button></div><div class="helper">Paste voiceover text or upload a .txt file. The editor automatically creates/updates <code>voiceover.txt</code> in this video folder.</div>${textarea('voiceover','Voiceover script',16,true)}<div class="button-row"><button class="btn btn-primary" id="saveVoiceoverNow">Save Voiceover TXT</button></div><p class="hint">Voiceover audio generation is not included; this stores its original script for audit.</p></article><article class="panel"><h2>Voiceover Checklist</h2><label class="check-row"><input type="checkbox" data-check="voiceoverReady" ${v.checklist.voiceoverReady?'checked':''}>Script / voiceover ready</label><p class="hint">Updated automatically when saved voiceover text is present. You may override the checklist manually.</p></article></div>`}
function renderFiles(v){return `<div class="detail-stack"><div class="media-input-row"><article class="panel"><div class="panel-heading"><h2>Thumbnail</h2><span class="tag">${aspectLabel(v.thumbnailWidth,v.thumbnailHeight)}</span></div>${makePreview('thumbnail')}${dropZone('thumbnail')}<div class="asset-actions"><button class="btn btn-outline" data-pick="thumbnail">Choose image</button>${staged.has('thumbnail')?'<button class="btn btn-primary" data-save-asset="thumbnail">Save to ERP</button>':''}</div></article><article class="panel"><div class="panel-heading"><h2>Final Video</h2><span class="tag">${aspectLabel(v.videoWidth,v.videoHeight)}</span></div>${makePreview('final')}<p class="hint">${v.finalDuration!==null?`Actual duration: ${fmtTime(v.finalDuration)} · `:''}${v.videoWidth&&v.videoHeight?`Resolution: ${v.videoWidth} × ${v.videoHeight}`:'Aspect ratio recognized when video metadata is readable'}</p>${dropZone('final')}<div class="asset-actions"><button class="btn btn-outline" data-pick="final">Choose video</button>${staged.has('final')?'<button class="btn btn-primary" data-save-asset="final">Save to ERP</button>':''}</div></article></div><article class="panel"><div class="panel-heading"><h2>TXT Files</h2><span class="hint">Open/edit text without leaving the ERP</span></div><div class="file-list">${Object.entries(TXT_FIELDS).map(([field,name])=>`<div class="file-row"><span>📄</span><span class="filename">${name}</span><span class="hint">Auto-save</span><button class="btn btn-outline btn-small" data-open-txt="${field}">Edit</button></div>`).join('')}${v.extras.map(name=>`<div class="file-row"><span>📄</span><span class="filename">${esc(name)}</span><span class="hint">Additional TXT</span><button class="btn btn-outline btn-small" data-edit-extra="${esc(name)}">Edit</button><button class="btn btn-danger btn-small" data-remove-extra="${esc(name)}">Delete</button></div>`).join('')}</div><hr class="subtle-divider"><div class="button-row"><button class="btn btn-outline" id="uploadExtra">Upload Additional TXT</button></div><div class="form-grid" style="margin-top:15px"><label class="form-label">Create an empty supporting TXT file<input id="extraName" class="field" placeholder="e.g. research_notes.txt"></label><div style="display:flex;align-items:center"><button class="btn btn-outline" id="createExtra">Create TXT File</button></div></div>${textFileEditing?`<hr class="subtle-divider"><label class="form-label">Editing ${esc(textFileEditing.name)}<textarea id="extraEditor" class="field text-editor large">${esc(textFileEditing.text)}</textarea></label><div class="button-row"><button class="btn btn-primary" id="saveExtra">Save TXT</button><button class="btn btn-outline" id="closeExtra">Close Editor</button></div>`:''}</article><article class="panel"><h2>Media Storage Behavior</h2><p class="hint">Drag a file or choose it, preview before saving, then click <b>Save to ERP</b>. This creates a new local copy inside the video folder. The source file stays where it was. Nothing is automatically deleted.</p></article></div>`}
function renderAudit(){return `<article class="panel"><div class="panel-heading"><h2>Activity History</h2><span class="hint">Saved locally in audit_log.json</span></div><div id="auditEntries"><div class="hint">Loading history…</div></div><hr class="subtle-divider"><div class="panel-heading"><h2>Previous TXT Versions</h2><span class="hint">Stored in versions/</span></div><div id="versionEntries"><div class="hint">Loading versions…</div></div></article>`}
function renderDetail(){const v=videoById(currentVideoId);if(!v)return;renderDetailHeader();document.querySelectorAll('#detailTabs .tab').forEach(b=>b.classList.toggle('active',b.dataset.tab===currentTab));$('detailsBody').innerHTML=currentTab==='overview'?renderOverview(v):currentTab==='prompts'?renderPrompts(v):currentTab==='voiceover'?renderVoiceover(v):currentTab==='files'?renderFiles(v):currentTab==='publishing'?renderVideoPublishing(v):renderAudit();if(currentTab==='prompts')updatePromptFeedback();if(currentTab==='audit')loadAudit(v);loadSavedMedia()}
async function loadSavedMedia(){const v=videoById(currentVideoId);if(!v)return;document.querySelectorAll('[data-saved-media]').forEach(async el=>{let fname=null;const key=el.dataset.savedMedia;if(key==='thumbnail')fname=v.thumbnailFile;else if(key==='final')fname=v.finalFile;else if(key.startsWith('clip:'))fname=v.clips.find(c=>c.number===Number(key.slice(5)))?.filename;if(!fname)return;try{const url=await mediaUrl(v,fname);if(el.isConnected){if(url)el.src=url;else el.replaceWith(Object.assign(document.createElement('span'),{className:'hint',textContent:'Media file missing. Metadata remains available.'}))}}catch(e){if(el.isConnected)el.alt='Cannot load media: '+e.message}})}
function updatePromptFeedback(){const el=$('promptFeedback');if(!el)return;const v=videoById(currentVideoId),p=parsePrompts(drafts.prompts||''),count=v?.manualCount===null?p.count:v?.manualCount;el.innerHTML=`<div class="inline-stats"><span>Detected prompts: <strong>${p.count}</strong></span><span>Effective count: <strong>${count}</strong></span><span>Est. video length: <strong>${fmtTime(count*(v?.clipSeconds||8))}</strong></span></div>${p.errors.length?`<div class="helper warn">Review formatting: ${esc(p.errors.join(' · '))}</div>`:`<p class="hint">${p.count?'Numbered sequence detected.':'Paste numbered prompts to begin.'} ${v?.manualCount!==null?'Manual count override is active.':''}</p>`}`}
function refreshClipPanel(){const el=$('clipPanel'),v=videoById(currentVideoId);if(el&&v){el.innerHTML=clipsPanel(v);loadSavedMedia()}}
async function loadAudit(v){const container=$('auditEntries'),versions=$('versionEntries');try{const folder=await folderForVideo(v),raw=await getText(folder,'audit_log.json'),entries=JSON.parse(raw||'[]');if(!Array.isArray(entries))throw Error('Malformed audit log');if(container&&container.isConnected)container.innerHTML=entries.length?[...entries].reverse().slice(0,150).map(entry=>`<div class="audit-row"><strong>${esc(entry.action)}</strong>${entry.detail?`<span class="detail">${esc(entry.detail)}</span>`:''}<time>${esc(fmtDate(entry.at))}</time></div>`).join(''):'<div class="hint">No activity recorded.</div>';const dir=await folder.getDirectoryHandle('versions',{create:true}),names=[];for await(const [name,h] of dir.entries())if(h.kind==='file'&&name.endsWith('.txt'))names.push(name);names.sort().reverse();if(versions&&versions.isConnected)versions.innerHTML=names.length?names.slice(0,100).map(name=>`<div class="file-row"><span>↶</span><span class="filename">${esc(name)}</span><button class="btn btn-outline btn-small" data-restore-version="${esc(name)}">Restore</button></div>`).join(''):'<div class="hint">No earlier TXT versions yet.</div>'}catch(e){if(container?.isConnected)container.textContent='Audit data unavailable: '+e.message}}
async function restoreVersion(name){const v=videoById(currentVideoId);if(!v||!isSafeLocalName(name)||!confirm(`Restore the TXT content in ${name}? The current text will be backed up first.`))return;try{await flushText();const dir=await folderForVideo(v),ver=await dir.getDirectoryHandle('versions'),text=await getText(ver,name);const field=Object.keys(TXT_FIELDS).find(k=>name.startsWith(TXT_FIELDS[k].replace('.txt','')+'-'));if(field){drafts[field]=text;editText(field,text);await flushText();renderDetail();toast('TXT restored from version: '+name)}else{const extra=v.extras.find(x=>name.startsWith(x.replace('.txt','')+'-'));if(!extra)throw Error('No matching TXT file found');const h=await dir.getFileHandle(extra,{create:true});await textVersion(dir,extra,await(await h.getFile()).text());await writeText(h,text);await commitVideo(v.id,()=>{},'TXT restored',extra);renderDetail();toast('TXT restored: '+extra)}}catch(e){toast('Restore failed: '+e.message,'error')}}
function renderAll(){renderShell();if(currentView==='details')renderDetail()}

/* --------------------------- Browser interactions ------------------------- */
let uploadTargetClipNumber=null;
function setTab(tab){if(!['overview','prompts','voiceover','files','publishing','audit'].includes(tab))return;currentTab=tab;renderDetail()}
function bindEvents(){
 $('menuToggle').onclick=()=>$('sidebar').classList.toggle('open');
 document.querySelectorAll('[data-view]').forEach(el=>el.addEventListener('click',async()=>{try{await flushText();view(el.dataset.view)}catch(e){toast('Save failed; navigation cancelled: '+e.message,'error')}}));
 document.querySelectorAll('[data-goto]').forEach(el=>el.addEventListener('click',async()=>{try{await flushText();view(el.dataset.goto)}catch(e){toast('Save failed: '+e.message,'error')}}));
 for(const id of ['connect','connectSide'])$(id).onclick=()=>connect();$('reconnect').onclick=()=>connect(true);$('disconnect').onclick=disconnect;
 $('addPage').onclick=()=>showPageDialog();$('pageForm').onsubmit=createPage;$('closePageDialog').onclick=$('cancelPageDialog').onclick=()=>$('pageDialog').close();
 for(const id of ['dashNewVideo','newVideo','inventoryNew'])$(id).onclick=showVideoDialog;$('videoForm').onsubmit=createVideo;$('closeVideoDialog').onclick=$('cancelVideoDialog').onclick=()=>$('videoDialog').close();
 $('backToProduction').onclick=async()=>{try{await flushText();view('production')}catch(e){toast('Save failed: '+e.message,'error')}};
 for(const prefix of ['production','inventory']){[`${prefix}Search`,`${prefix}PageFilter`,`${prefix}StatusFilter`].forEach(id=>$(id).addEventListener(id.endsWith('Search')?'input':'change',renderVideoLists))}
 $('export').onclick=exportData;$('import').onclick=()=>$('importFile').click();$('importFile').onchange=e=>importData(e.target.files[0]);
 $('promptUpload').onchange=e=>{uploadText('prompts',e.target.files[0]);e.target.value=''};
 $('voiceoverUpload').onchange=e=>{uploadText('voiceover',e.target.files[0]);e.target.value=''};
 $('thumbnailUpload').onchange=e=>{stageFile('thumbnail',e.target.files[0]);e.target.value=''};
 $('finalUpload').onchange=e=>{stageFile('final',e.target.files[0]);e.target.value=''};
 $('clipUpload').onchange=e=>{stageFile('clip',e.target.files[0],uploadTargetClipNumber);e.target.value=''};
 $('extraTextUpload').onchange=e=>{updateExtraFile(e.target.files[0]);e.target.value=''};
 document.addEventListener('click',async e=>{
  const t=e.target.closest('button,[data-drop-kind]');if(!t)return;
  if(t.dataset.openVideo){await openVideo(t.dataset.openVideo);return}
  if(t.dataset.pageEdit){showPageDialog(t.dataset.pageEdit);return}
  if(t.dataset.pageDelete){await deletePage(t.dataset.pageDelete);return}
  if(t.dataset.duplicate){await duplicateVideo(t.dataset.duplicate);return}
  if(t.dataset.tab){try{await flushText();setTab(t.dataset.tab)}catch(err){toast('Save failed: '+err.message,'error')}return}
  if(t.dataset.tabOpen){try{await flushText();setTab(t.dataset.tabOpen)}catch(err){toast('Save failed: '+err.message,'error')}return}
  if(t.id==='saveNow'||t.id==='savePromptsNow'||t.id==='saveVoiceoverNow'){await saveNow();return}
  if(t.id==='uploadPrompts'){$('promptUpload').click();return}
  if(t.id==='uploadVoiceover'){$('voiceoverUpload').click();return}
  if(t.dataset.dropKind||t.dataset.pick){const kind=t.dataset.dropKind||t.dataset.pick,number=t.dataset.dropNumber?Number(t.dataset.dropNumber):null;chooseAsset(kind,number);return}
  if(t.dataset.uploadClip){chooseAsset('clip',Number(t.dataset.uploadClip));return}
  if(t.dataset.clipPreview){selectedClipNumber=selectedClipNumber===Number(t.dataset.clipPreview)?null:Number(t.dataset.clipPreview);refreshClipPanel();return}
  if(t.dataset.saveAsset){await saveStaged(t.dataset.saveAsset,t.dataset.number?Number(t.dataset.number):null);return}
  if(t.id==='applyManualCount'){await applyPromptCount(true);return}
  if(t.id==='useDetectedCount'){await applyPromptCount(false);return}
  if(t.id==='uploadExtra'){$('extraTextUpload').click();return}
  if(t.id==='createExtra'){await updateExtraFile(null,$('extraName').value.trim());return}
  if(t.dataset.openTxt){try{await flushText();setTab(t.dataset.openTxt==='prompts'?'prompts':t.dataset.openTxt==='voiceover'?'voiceover':'overview');setTimeout(()=>document.getElementById('edit-'+t.dataset.openTxt)?.focus(),50)}catch(err){toast(err.message,'error')}return}
  if(t.dataset.editExtra){await openExtraEditor(t.dataset.editExtra);return}
  if(t.dataset.removeExtra){await removeExtra(t.dataset.removeExtra);return}
  if(t.id==='saveExtra'){await saveExtraEditor();return}
  if(t.id==='closeExtra'){try{await flushText();textFileEditing=null;renderDetail()}catch(err){toast('Save failed: '+err.message,'error')}return}
  if(t.dataset.restoreVersion){await restoreVersion(t.dataset.restoreVersion);return}
 });
 document.addEventListener('input',e=>{const el=e.target;if(el.dataset.editText){editText(el.dataset.editText,el.value);return}if(el.id==='extraEditor'&&textFileEditing){textFileEditing.text=el.value;textFileEditing.dirty=el.value!==textFileEditing.saved;setSaveStatus(textFileEditing.dirty?'dirty':'saved');clearTimeout(extraSaveTimer);if(textFileEditing.dirty)extraSaveTimer=setTimeout(()=>saveExtraEditor(true).catch(()=>{}),950);return}});
 document.addEventListener('change',e=>{const el=e.target;if(el.id==='detailStatus'){changeStatus(el.value);return}if(el.dataset.clipStatus){updateClipStatus(Number(el.dataset.clipStatus),el.value);return}if(el.dataset.check){toggleCheck(el.dataset.check,el.checked);return}if(el.id==='clipSecondsSelect'){changeClipSeconds(Number(el.value));return}});
 document.addEventListener('dragover',e=>{const zone=e.target.closest('[data-drop-kind]');if(zone){e.preventDefault();e.dataTransfer.dropEffect='copy';zone.classList.add('dragover')}});
 document.addEventListener('dragleave',e=>{const zone=e.target.closest('[data-drop-kind]');if(zone)zone.classList.remove('dragover')});
 document.addEventListener('drop',e=>{const zone=e.target.closest('[data-drop-kind]');if(!zone)return;e.preventDefault();zone.classList.remove('dragover');const file=e.dataTransfer.files[0];if(file)stageFile(zone.dataset.dropKind,file,zone.dataset.dropNumber?Number(zone.dataset.dropNumber):null)});
 document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();saveNow()}if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-drop-kind]')){e.preventDefault();const z=e.target;chooseAsset(z.dataset.dropKind,z.dataset.dropNumber?Number(z.dataset.dropNumber):null)}});
 window.addEventListener('beforeunload',e=>{if(dirty.size||textFileEditing?.dirty){e.preventDefault();e.returnValue=''}});
 document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden'&&(dirty.size||textFileEditing?.dirty))flushText().catch(()=>{})});
 bindPhase3Events();
}
function chooseAsset(kind,number=null){if(kind==='thumbnail')$('thumbnailUpload').click();else if(kind==='final')$('finalUpload').click();else if(kind==='clip'){uploadTargetClipNumber=number;$('clipUpload').click()}}
async function initialize(){if(initDone)return;initDone=true;bindEvents();plannerDate=istDate();renderAll();clockTimer=setInterval(()=>{if(currentView==='world')tickClocks()},1000);try{const handle=await rememberGet();if(handle){if(await permit(handle,false))await showConnected(handle);else{toast('Saved folder found. Click Reconnect Saved to grant Chrome permission.');$('sideDetails').textContent='Click Reconnect Saved in Settings'}}}catch(e){workspace=null;data=emptyData();renderAll();toast('Reconnect your folder: '+e.message,'error')}}
function renderVideoPublishing(v){
 const records=data.schedule.filter(x=>x.videoId===v.id).sort((a,b)=>a.date.localeCompare(b.date)||a.time.localeCompare(b.time));
 return `<article class="panel"><div class="panel-heading"><div><h2>Publishing Assignments</h2><p class="hint">All dates and times use IST. Slots are manually assigned per Facebook page.</p></div><button class="btn btn-primary btn-small" data-open-planner="${esc(v.pageId)}">Open Planner →</button></div>${records.length?`<div class="table-scroll"><table class="erp-table"><thead><tr><th>Date</th><th>Time (IST)</th><th>Audience</th><th>Slot status</th><th>Facebook post URL</th></tr></thead><tbody>${records.map(a=>`<tr><td>${esc(prettyDay(a.date))}</td><td>${esc(a.time)}</td><td>${esc(SLOTS.find(s=>s[0]===a.time)?.[1]||'')}</td><td><span class="status-tag ${a.published?'published':'scheduled'}">${a.published?'Published':'Assigned'}</span></td><td>${a.postUrl?`<a href="${esc(a.postUrl)}" target="_blank" rel="noopener noreferrer">Open post ↗</a>`:'—'}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">This video has no publishing slot yet. Open the planner to assign one.</div>'}</article>`;
}
/* ------------------ Phase 3 · Planner, Kanban, Search, Clocks ------------------ */
const WORLD_ZONES=[
  {city:'New York',country:'United States · Eastern',zone:'America/New_York',flag:'🇺🇸'},
  {city:'Los Angeles',country:'United States · Pacific',zone:'America/Los_Angeles',flag:'🇺🇸'},
  {city:'London',country:'United Kingdom',zone:'Europe/London',flag:'🇬🇧'},
  {city:'Sydney',country:'Australia · Eastern',zone:'Australia/Sydney',flag:'🇦🇺'},
  {city:'Berlin',country:'Germany · Central Europe',zone:'Europe/Berlin',flag:'🇩🇪'},
  {city:'Paris',country:'France · Central Europe',zone:'Europe/Paris',flag:'🇫🇷'}
];
function istDate(d=new Date()){
 const parts=new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(d);
 const get=t=>parts.find(x=>x.type===t).value;return `${get('year')}-${get('month')}-${get('day')}`;
}
function offsetDate(date,days){const d=new Date(`${date}T12:00:00Z`);d.setUTCDate(d.getUTCDate()+days);return d.toISOString().slice(0,10)}
function prettyDay(d){return new Intl.DateTimeFormat('en-GB',{weekday:'short',day:'numeric',month:'short',year:'numeric',timeZone:'UTC'}).format(new Date(d+'T12:00:00Z'))}
function slotAt(day,pid,time){return data.schedule.find(s=>s.date===day&&s.pageId===pid&&s.time===time)}
function dailyNumbers(day,pages=data.pages){const ids=new Set(pages.map(p=>p.id)),list=data.schedule.filter(s=>s.date===day&&ids.has(s.pageId));return {total:pages.length*SLOTS.length,assigned:list.length,published:list.filter(x=>x.published).length,empty:pages.length*SLOTS.length-list.length}}
function rangeNumbers(day,days=7){let total=0,assigned=0,published=0,empty=0;for(let k=0;k<days;k++){const d=dailyNumbers(offsetDate(day,k));total+=d.total;assigned+=d.assigned;published+=d.published;empty+=d.empty}return {total,assigned,published,empty}}
function forecastHTML(day){if(!data.pages.length)return '<div class="empty">Create a Facebook page to start planning your 8 daily time slots.</div>';
 const tomorrow=dailyNumbers(offsetDate(day,1)),seven=rangeNumbers(day);
 return `<div class="forecast-top"><div class="forecast-stat"><span>Tomorrow's empty slots</span><strong>${tomorrow.empty}</strong><small>${tomorrow.assigned} of ${tomorrow.total} assigned</small></div><div class="forecast-stat"><span>Next 7 days needed</span><strong>${seven.empty}</strong><small>${seven.assigned} of ${seven.total} assigned</small></div></div><div class="forecast-days">${Array.from({length:7},(_,i)=>{const date=offsetDate(day,i),n=dailyNumbers(date),pct=n.total?Math.round(n.assigned/n.total*100):0;return `<div class="forecast-day"><span>${esc(prettyDay(date).replace(/,? \d{4}$/,''))}</span><div class="forecast-track"><i style="width:${pct}%"></i></div><strong>${n.assigned}/${n.total}</strong></div>`}).join('')}</div><p class="hint">Capacity requirements only. Videos are assigned manually, and unpublished slots are not auto-uploaded.</p>`;
}
function renderPhase3Shell(){
 const day=istDate(),forecast=$('dashboardForecast');if(forecast)forecast.innerHTML=forecastHTML(day);
 const preview=$('slotsPreview');if(preview){preview.innerHTML=SLOTS.map(([time,audience])=>{const matches=data.schedule.filter(x=>x.date===day&&x.time===time),assigned=matches.length,pub=matches.filter(x=>x.published).length;return `<div class="slot-row"><time class="slot-time">${time}</time><span class="hint">${assigned}/${data.pages.length} pages assigned · ${pub} published</span><span class="tag">${audience}</span></div>`}).join('')}
 if($('planner')?.classList.contains('active'))renderPlanner();
 if($('search')?.classList.contains('active'))renderGlobalSearch(false);
}
function renderPlanner(){
 if(!plannerDate)plannerDate=istDate();const dateInput=$('plannerDate'),pageSelect=$('plannerPage');if(!dateInput||!pageSelect)return;
 dateInput.value=plannerDate;
 const options='<option value="all">All Facebook pages</option>'+data.pages.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('');
 if(pageSelect.innerHTML!==options)pageSelect.innerHTML=options;
 if(plannerPage!=='all'&&!pageById(plannerPage))plannerPage='all';pageSelect.value=plannerPage;
 const visible=data.pages.filter(p=>plannerPage==='all'||p.id===plannerPage),stats=dailyNumbers(plannerDate,visible);
 $('plannerStats').innerHTML=[['Daily slots',stats.total,'blue'],['Assigned',stats.assigned,'purple'],['Published',stats.published,'green'],['Empty / needed',stats.empty,'amber']].map(([name,n,cls])=>`<div class="planner-metric ${cls}"><small>${name}</small><strong>${n}</strong></div>`).join('');
 $('plannerRows').innerHTML=visible.length?visible.map(page=>{
  const count=dailyNumbers(plannerDate,[page]);
  const sorted=[...data.videos].filter(v=>v.pageId===page.id).sort((a,b)=>{
   const rank=x=>['Ready','Scheduled','In Production','Draft','Published'].indexOf(x.status);
   return rank(a)-rank(b)||b.updatedAt.localeCompare(a.updatedAt)
  });
  const rows=SLOTS.map(([time,audience])=>{
   const a=slotAt(plannerDate,page.id,time),v=a?videoById(a.videoId):null;
   const videoSelect=`<select class="field slot-select" data-slot-video="1" data-page="${esc(page.id)}" data-day="${plannerDate}" data-time="${time}" aria-label="Assign video to ${time} on ${esc(page.name)}"><option value="">— Empty slot —</option>${sorted.map(x=>`<option value="${esc(x.id)}" ${a?.videoId===x.id?'selected':''}>${esc(x.id)} · ${esc(x.title.slice(0,70))} [${esc(x.status)}]</option>`).join('')}</select>`;
   const media=v?thumbMarkup(v,'thumb'):'<div class="thumb vacant-thumb">＋</div>';
   const status=a?`<span class="status-tag ${a.published?'published':'scheduled'}">${a.published?'Published':'Assigned'}</span>`:'<span class="status-tag draft">Empty</span>';
   const actions=a?`<div class="slot-actions"><button type="button" class="btn ${a.published?'btn-outline':'btn-primary'} btn-small" data-mark-slot="${a.published?'unpublish':'publish'}" data-page="${esc(page.id)}" data-day="${plannerDate}" data-time="${time}">${a.published?'↶ Undo published':'✓ Mark published'}</button><button type="button" class="btn btn-quiet btn-small" data-clear-slot="1" data-page="${esc(page.id)}" data-day="${plannerDate}" data-time="${time}">Clear</button></div>`:'';
   const urlInput=a?`<label class="url-label">Facebook post URL (optional)<input class="field url-input" type="url" placeholder="https://facebook.com/..." value="${esc(a.postUrl)}" data-slot-url="1" data-page="${esc(page.id)}" data-day="${plannerDate}" data-time="${time}"></label>`:'';
   return `<div class="publish-slot ${a?.published?'published-slot':''}"><div class="publish-hour"><b>${time}</b><span>${audience}</span></div>${media}<div class="publish-main"><div class="publish-video-title">${v?`<button type="button" class="text-button" data-open-video="${esc(v.id)}">${esc(v.title)}</button>`:'<span class="hint">No video assigned</span>'}${v?`<small class="hint">${esc(v.id)} · ${esc(v.status)} · ${aspectLabel(v.videoWidth,v.videoHeight)}</small>`:''}</div>${videoSelect}${urlInput}</div><div class="publish-end">${status}${actions}</div></div>`
  }).join('');
  return `<article class="panel publishing-page"><div class="panel-heading"><div><h2>${esc(page.name)}</h2><span class="hint">${esc(page.audience)} · ${count.assigned}/8 assigned · ${count.published} published</span></div><span class="hint">${esc(prettyDay(plannerDate))}</span></div><div class="publishing-rows">${rows}</div></article>`
 }).join(''):'<article class="panel"><div class="empty">No Facebook pages found. Create a page first, then choose videos for each slot.</div></article>';
 $('plannerForecast').innerHTML=forecastHTML(istDate());renderThumbnails();
}
async function assignSlot(day,pageId,time,videoId){
 if(!requireWorkspace()||!isValidDate(day)||!SLOTS.some(s=>s[0]===time)||!pageById(pageId))return;
 const current=slotAt(day,pageId,time);if(current?.videoId===videoId)return;
 const v=videoId?videoById(videoId):null;
 if(videoId&&(!v||v.pageId!==pageId)){toast('Choose a video from this Facebook page.','error');renderPlanner();return}
 if(current?.published&&!confirm('This slot is marked published. Change its video and preserve the previous audit history?')){renderPlanner();return}
 if(videoId){const duplicate=data.schedule.find(s=>s.date===day&&s.pageId===pageId&&s.videoId===videoId&&s.time!==time);if(duplicate&&!confirm(`${videoId} is already assigned at ${duplicate.time} on this page. Assign it twice on the same day?`)){renderPlanner();return}}
 try{await flushText();await queued(async()=>{
  const next=structuredClone(data),idx=next.schedule.findIndex(a=>a.date===day&&a.pageId===pageId&&a.time===time);if(idx!==-1)next.schedule.splice(idx,1);
  if(videoId){next.schedule.push({date:day,pageId,time,videoId,published:false,postUrl:'',createdAt:current?.createdAt||now(),updatedAt:now(),publishedAt:null});const item=next.videos.find(x=>x.id===videoId);if(item.status==='Ready')item.status='Scheduled';item.updatedAt=now()}
  await saveData(next);if(current)await appendAudit(currentVideoRef(current),'Publishing assignment changed',`${day} ${time} cleared or replaced`);if(v)await syncVideoMirrorAndAudit(videoId,'Publishing slot assigned',`${day} ${time} IST · ${pageById(pageId).name}`);
 });toast(videoId?'Slot assigned and saved locally.':'Slot cleared and saved locally.');renderPlanner()}
 catch(e){toast('Slot update failed: '+e.message,'error');renderPlanner()}
}
function currentVideoRef(a){return videoById(a.videoId)||{id:a.videoId,pageId:a.pageId}}
async function syncVideoMirrorAndAudit(id,action,detail){const v=videoById(id);if(!v)return;try{const dir=await folderForVideo(v);await writeJSON(await dir.getFileHandle('metadata.json',{create:true}),v)}catch(e){toast('Master saved, but video metadata mirror failed: '+e.message,'error')}await appendAudit(v,action,detail)}
async function publishSlot(day,pageId,time,published){
 const prev=slotAt(day,pageId,time);if(!prev)return;
 if(prev.published===published)return;
 if(published&&!confirm(`Confirm you manually published ${prev.videoId} for ${day} at ${time} IST? The ERP does not upload to Facebook.`))return;
 if(!published&&!confirm('Undo the published flag for this slot? This does NOT remove the Facebook post.'))return;
 try{await flushText();await queued(async()=>{const next=structuredClone(data),record=next.schedule.find(a=>a.date===day&&a.pageId===pageId&&a.time===time);if(!record)return;record.published=published;record.publishedAt=published?now():null;record.updatedAt=now();const v=next.videos.find(x=>x.id===record.videoId);if(published&&v){v.status='Published';v.checklist.published=true;v.updatedAt=now()}else if(!published&&v&&!next.schedule.some(s=>s.videoId===v.id&&s.published)){v.status=v.status==='Published'?'Scheduled':v.status;v.checklist.published=false;v.updatedAt=now()}await saveData(next);await syncVideoMirrorAndAudit(record.videoId,published?'Publishing confirmed':'Publishing mark reversed',`${day} ${time} IST`)});renderPlanner();toast(published?'Marked published in your local audit.':'Published mark reversed.')}catch(e){toast('Publishing status failed: '+e.message,'error')}
}
async function updateSlotUrl(day,pageId,time,url){const item=slotAt(day,pageId,time);if(!item||item.postUrl===url.trim())return;
 if(url.trim()&&!/^https?:\/\//i.test(url.trim())){toast('Use an http:// or https:// post URL.','error');renderPlanner();return}
 if(url.trim().length>1500){toast('Post URL is too long.','error');renderPlanner();return}
 try{await queued(async()=>{const next=structuredClone(data),a=next.schedule.find(x=>x.date===day&&x.pageId===pageId&&x.time===time);if(!a)return;a.postUrl=url.trim();a.updatedAt=now();await saveData(next);await appendAudit(currentVideoRef(a),'Post URL updated',`${day} ${time} IST`)});renderPlanner();toast('Post URL saved.')}catch(e){toast('Cannot save post URL: '+e.message,'error')}
}
function renderKanban(){const board=$('kanbanBoard'),table=$('inventoryTablePanel');if(!board||!table)return;
 const kanban=inventoryLayout==='kanban';board.hidden=!kanban;table.hidden=kanban;
 $('layoutTable').className='btn '+(kanban?'btn-outline':'btn-primary')+' btn-small';$('layoutKanban').className='btn '+(kanban?'btn-primary':'btn-outline')+' btn-small';
 if(!kanban)return;
 const videos=filteredRecords('inventory');board.innerHTML=STATES.map(status=>{
 const records=videos.filter(v=>v.status===status);
 return `<section class="kanban-column" data-kanban-column="${esc(status)}"><div class="kanban-heading"><span>${esc(status)}</span><strong>${records.length}</strong></div><div class="kanban-cards">${records.map(v=>{const c=countStats(v);return `<article class="kanban-card" draggable="true" data-kanban-card="${esc(v.id)}" aria-label="Drag ${esc(v.title)} to change production status">${thumbMarkup(v,'thumb')}<div class="kanban-card-content"><button type="button" class="text-button" data-open-video="${esc(v.id)}">${esc(v.title)}</button><span class="hint">${esc(v.id)} · ${esc(pageById(v.pageId)?.name||'')}</span><span class="hint">Clips ${c.done}/${c.total} · ${fmtTime(v.promptCount*v.clipSeconds)}</span><label class="kanban-move-label">Move to <select class="field kanban-move" data-move-video="${esc(v.id)}" aria-label="Move ${esc(v.id)} to stage">${STATES.map(st=>`<option ${st===v.status?'selected':''}>${esc(st)}</option>`).join('')}</select></label></div></article>`}).join('')||'<div class="kanban-empty">Drop videos here</div>'}</div></section>`
 }).join('');renderThumbnails();
}
async function moveKanban(id,status){if(!STATES.includes(status))return;const v=videoById(id);if(!v||v.status===status)return;
 if(status==='Published'&&!confirm(`Mark ${id} as Published? This only updates your ERP record; it does not publish the video on Facebook.`)){renderKanban();return}
 try{await flushText();await commitVideo(id,r=>{r.status=status;r.checklist.published=status==='Published';if(status==='Ready')r.checklist.readyToPublish=true},'Kanban stage changed',`${v.status} → ${status}`);renderKanban();toast(`${id} moved to ${status}`)}catch(e){toast('Could not change stage: '+e.message,'error');renderKanban()}
}
function zoneTime(zone){const d=new Date(),parts=new Intl.DateTimeFormat('en-GB',{timeZone:zone,year:'numeric',month:'short',day:'numeric',weekday:'short',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).formatToParts(d);const val=k=>parts.find(p=>p.type===k)?.value||'0';return {hour:Number(val('hour'))%24,min:Number(val('minute')),sec:Number(val('second')),day:`${val('weekday')}, ${val('day')} ${val('month')} ${val('year')}`}}
function zoneActivity(h,m){const t=h+m/60;if(t>=17&&t<20)return {label:'Preferred window',style:'prime',order:0};if(t>=9&&t<17)return {label:'Working hours',style:'active',order:1};if(t>=20||t<1)return {label:'Evening',style:'evening',order:2};return {label:'Low activity',style:'quiet',order:3}}
function renderClocks(){const grid=$('clocksGrid');if(!grid)return;grid.innerHTML=WORLD_ZONES.map((z,i)=>`<article class="world-clock" id="clock-${i}"><div class="clock-top"><span class="clock-flag">${z.flag}</span><div><strong>${esc(z.city)}</strong><small>${esc(z.country)}</small></div><span class="clock-activity" data-activity>—</span></div><div class="clock-center"><div class="clock-face"><span class="clock-number n12">12</span><span class="clock-number n3">3</span><span class="clock-number n6">6</span><span class="clock-number n9">9</span><div class="clock-hand hours" data-hour-hand></div><div class="clock-hand minutes" data-minute-hand></div><div class="clock-hand seconds" data-second-hand></div><span class="clock-pin"></span></div><div class="clock-text"><strong data-digital>--:--:--</strong><small data-day>—</small><span class="clock-description" data-description>—</span></div></div></article>`).join('');tickClocks()}
function tickClocks(){
 const highlights=[];
 for(let i=0;i<WORLD_ZONES.length;i++){
  const el=$(`clock-${i}`);if(!el)continue;const {hour,min,sec,day}=zoneTime(WORLD_ZONES[i].zone),activity=zoneActivity(hour,min);
  el.dataset.activityColor=activity.style;highlights.push({city:WORLD_ZONES[i].city,...activity});el.querySelector('[data-hour-hand]').style.transform=`translateX(-50%) rotate(${(hour%12)*30+min*.5}deg)`;
  el.querySelector('[data-minute-hand]').style.transform=`translateX(-50%) rotate(${min*6+sec*.1}deg)`;
  el.querySelector('[data-second-hand]').style.transform=`translateX(-50%) rotate(${sec*6}deg)`;
  el.querySelector('[data-digital]').textContent=`${String(hour).padStart(2,'0')}:${String(min).padStart(2,'0')}:${String(sec).padStart(2,'0')}`;
  el.querySelector('[data-day]').textContent=day;el.querySelector('[data-activity]').textContent=activity.label;
  el.querySelector('[data-description]').textContent=activity.style==='prime'?'Your preferred posting window':activity.style==='active'?'Standard daytime working hours':activity.style==='evening'?'Evening audience window':'Outside your preferred hours';
 }
 const prime=highlights.filter(x=>x.style==='prime'),active=highlights.filter(x=>x.style==='active');const best=$('audienceNow');if(best){best.innerHTML=prime.length?`<strong>★ Preferred evening window now</strong><span>${prime.map(x=>esc(x.city)).join(' · ')} — 5:00–8:00 PM local time</span>`:active.length?`<strong>◷ Working hours now</strong><span>${active.map(x=>esc(x.city)).join(' · ')} — none currently in your 5:00–8:00 PM preferred window</span>`:'<strong>◷ No preferred windows currently active</strong><span>Check the local clocks below for upcoming evening windows.</span>'}const ist=zoneTime('Asia/Kolkata');$('istNow').textContent=`🇮🇳 IST ${String(ist.hour).padStart(2,'0')}:${String(ist.min).padStart(2,'0')}:${String(ist.sec).padStart(2,'0')}`;
}
function renderGlobalSearch(doSearch=true){const el=$('globalPage');if(!el)return;
 const old=el.value||'all',html='<option value="all">All Facebook pages</option>'+data.pages.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('');if(el.innerHTML!==html)el.innerHTML=html;el.value=old==='all'||pageById(old)?old:'all';
 if(doSearch&&$('globalQuery').value.trim())queueSearch();
}
function queueSearch(){clearTimeout(searchTimer);searchTimer=setTimeout(()=>searchAll(),220)}
async function getSearchContent(v){if(searchCache.has(v.id))return searchCache.get(v.id);
 const current=workspace;let txt={prompts:'',voiceover:'',notes:[]};
 try{const folder=await folderForVideo(v),p=await getText(folder,'prompts.txt'),vo=await getText(folder,'voiceover.txt');txt.prompts=p;txt.voiceover=vo;
  for(const name of (v.extras||[])){if(!name.toLowerCase().endsWith('.txt'))continue;try{txt.notes.push({name,text:await getText(folder,name)})}catch(e){if(e.name!=='NotFoundError')throw e}}
 }catch(e){txt.error=e.message}
 if(workspace===current)searchCache.set(v.id,txt);return txt
}
function highlighted(text,needle){text=String(text||'');const at=text.toLowerCase().indexOf(needle.toLowerCase());if(at===-1)return esc(text.slice(0,150));const start=Math.max(0,at-65),end=Math.min(text.length,at+needle.length+110);return `${start?'…':''}${esc(text.slice(start,at))}<mark>${esc(text.slice(at,at+needle.length))}</mark>${esc(text.slice(at+needle.length,end))}${end<text.length?'…':''}`}
async function searchAll(){
 const req=++searchRequestId,q=$('globalQuery')?.value.trim()||'',results=$('searchResults'),state=$('searchState');if(!results||!state)return;
 if(!q){state.textContent='Type a word or phrase to search videos and local TXT content.';results.innerHTML='';return}
 if(!workspace){state.textContent='Connect your Mac workspace to search local TXT files.';results.innerHTML='';return}
 const page=$('globalPage').value,status=$('globalStatus').value,aspect=$('globalAspect').value,audience=$('globalAudience').value,day=$('globalDate').value,items=data.videos.filter(v=>(page==='all'||page===v.pageId)&&(status==='all'||status===v.status)&&(aspect==='all'||aspect===aspectLabel(v.videoWidth,v.videoHeight))&&(audience==='all'||pageById(v.pageId)?.audience===audience)&&(!day||data.schedule.some(s=>s.videoId===v.id&&s.date===day)));
 state.textContent=`Searching ${items.length} video records and their local TXT files…`;
 const matches=[];let ix=0,processed=0,failures=0;
 async function worker(){while(ix<items.length){if(req!==searchRequestId)return;const v=items[ix++],content=await getSearchContent(v);if(req!==searchRequestId)return;if(content.error)failures++;
  const sources=[['Video ID',v.id],['Title',v.title],['Description',v.description],['Page',pageById(v.pageId)?.name||''],['Audience',pageById(v.pageId)?.audience||''],['Production Status',v.status],['Aspect Ratio',aspectLabel(v.videoWidth,v.videoHeight)],['Clips',v.clips.map(c=>`${c.number}. ${c.status}`).join(' | ')],['Veo Prompts',content.prompts],['Voiceover',content.voiceover],['Publishing Dates',data.schedule.filter(s=>s.videoId===v.id).map(s=>`${s.date} ${s.time} IST`).join(' ')],...content.notes.map(n=>[`Notes: ${n.name}`,n.text])];
  const found=sources.filter(([,text])=>String(text).toLowerCase().includes(q.toLowerCase()));if(found.length)matches.push({v,found});processed++;if(processed%15===0&&req===searchRequestId)state.textContent=`Searched ${processed} / ${items.length} records…`;
 }}
 await Promise.all(Array.from({length:Math.min(items.length,4)},worker));if(req!==searchRequestId)return;
 matches.sort((a,b)=>b.v.updatedAt.localeCompare(a.v.updatedAt));state.textContent=`${matches.length} matching video${matches.length===1?'':'s'} · ${processed} searched${failures?` · ${failures} local folder(s) unreadable`:''}`;
 results.innerHTML=matches.length?matches.map(({v,found})=>`<article class="panel search-hit"><div class="search-hit-header">${thumbMarkup(v,'thumb')}<div class="search-hit-title"><span class="hint">${esc(v.id)} · ${esc(pageById(v.pageId)?.name||'Unknown page')}</span><button type="button" class="text-button" data-open-video="${esc(v.id)}">${esc(v.title)}</button><span class="hint">${esc(v.status)} · ${found.length} matching field(s)</span></div><button type="button" class="btn btn-outline btn-small" data-open-video="${esc(v.id)}">Open record</button></div><div class="search-snippets">${found.slice(0,4).map(([label,text])=>`<div class="search-snippet"><span class="tag">${esc(label)}</span><span>${highlighted(text,q)}</span></div>`).join('')}</div></article>`).join(''):'<div class="empty">No matching records. Try another word or refresh the TXT search index.</div>';renderThumbnails();
}
function bindPhase3Events(){
 $('quickSearch').onclick=async()=>{try{await flushText();view('search');$('globalQuery').focus()}catch(e){toast('Save failed: '+e.message,'error')}};
 $('layoutTable').onclick=()=>{inventoryLayout='table';renderKanban()};$('layoutKanban').onclick=()=>{inventoryLayout='kanban';renderKanban()};
 $('plannerDate').onchange=e=>{if(isValidDate(e.target.value)){plannerDate=e.target.value;renderPlanner()}};
 $('plannerPage').onchange=e=>{plannerPage=e.target.value;renderPlanner()};
 $('plannerPrev').onclick=()=>{plannerDate=offsetDate(plannerDate,-1);renderPlanner()};
 $('plannerNext').onclick=()=>{plannerDate=offsetDate(plannerDate,1);renderPlanner()};
 $('plannerToday').onclick=()=>{plannerDate=istDate();renderPlanner()};
 $('globalQuery').oninput=queueSearch;for(const id of ['globalPage','globalStatus','globalAspect','globalAudience','globalDate'])$(id).onchange=queueSearch;
 $('clearSearchFilters').onclick=()=>{for(const id of ['globalPage','globalStatus','globalAspect','globalAudience'])$(id).value='all';$('globalDate').value='';queueSearch()};
 $('refreshSearch').onclick=()=>{searchCache.clear();searchRequestId++;queueSearch();toast('Local TXT search index reset. Next search rereads the files.')};
 document.addEventListener('change',e=>{const el=e.target;
  if(el.dataset.slotVideo){assignSlot(el.dataset.day,el.dataset.page,el.dataset.time,el.value);return}
  if(el.dataset.slotUrl){updateSlotUrl(el.dataset.day,el.dataset.page,el.dataset.time,el.value);return}
  if(el.dataset.moveVideo){moveKanban(el.dataset.moveVideo,el.value);return}
 });
 document.addEventListener('click',e=>{const btn=e.target.closest('button');if(!btn)return;
  if(btn.dataset.markSlot){publishSlot(btn.dataset.day,btn.dataset.page,btn.dataset.time,btn.dataset.markSlot==='publish');return}
  if(btn.dataset.clearSlot){assignSlot(btn.dataset.day,btn.dataset.page,btn.dataset.time,'');return}
  if(btn.dataset.openPlanner){plannerPage=btn.dataset.openPlanner;plannerDate=istDate();view('planner');return}
 });
 document.addEventListener('dragstart',e=>{const card=e.target.closest('[data-kanban-card]');if(!card)return;e.dataTransfer.setData('text/plain',card.dataset.kanbanCard);e.dataTransfer.effectAllowed='move';card.classList.add('dragging')});
 document.addEventListener('dragend',e=>{const card=e.target.closest('[data-kanban-card]');if(card)card.classList.remove('dragging');document.querySelectorAll('[data-kanban-column]').forEach(el=>el.classList.remove('drop-ready'))});
 document.addEventListener('dragover',e=>{const col=e.target.closest('[data-kanban-column]');if(!col)return;e.preventDefault();e.dataTransfer.dropEffect='move';col.classList.add('drop-ready')});
 document.addEventListener('dragleave',e=>{const col=e.target.closest('[data-kanban-column]');if(col&&!col.contains(e.relatedTarget))col.classList.remove('drop-ready')});
 document.addEventListener('drop',e=>{const col=e.target.closest('[data-kanban-column]');if(!col)return;e.preventDefault();col.classList.remove('drop-ready');const id=e.dataTransfer.getData('text/plain');if(/^VID-\d{4,}$/.test(id))moveKanban(id,col.dataset.kanbanColumn)});
}

document.addEventListener('DOMContentLoaded',initialize);